select t.id, t.item_id, t.limit_purchase_id, t.max_discount_amount, t.start_time, t.advance_time, t.end_time, t.min_price, t.sku_value from limit_purchase_item t where t.item_id = #{itemId} and t.deleted = false and t.state = 1 and now() between t.start_time and t.end_time
and t.merchant_id = #{merchantId}
limit 1

select count(1) from limit_purchase_item
where deleted = false and state = 1 and now() < end_time and merchant_id = #{merchantId}

    and limit_purchase_id <> #{limitId}

and item_id in

    #{item}
